for code, vals in X.items():
    assert len(vals) == len(KEYS), (code, len(vals))
    assert len(vals[0]) <= 132, code
    f = OUT / code / "messages.json"
    msgs = json.loads(f.read_text(encoding="utf-8"))
    for k, v in zip(KEYS, vals):
        msgs[k] = {"message": v}
    f.write_text(json.dumps(msgs, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")

existing = {p.name for p in OUT.iterdir() if p.is_dir()}
assert existing == set(X), existing ^ set(X)
print("ok", len(X))
